import{K as d,a as r,c as l,b as t,k as o,q as i,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Excel 公式、相对引用与绝对引用","description":"学会公式计算顺序、相对绝对混合引用、跨表引用、结构化引用、填充和公式错误排查，制作税额与乘法表示例。","frontmatter":{"title":"Excel 公式、相对引用与绝对引用","description":"学会公式计算顺序、相对绝对混合引用、跨表引用、结构化引用、填充和公式错误排查，制作税额与乘法表示例。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"学会公式计算顺序、相对绝对混合引用、跨表引用、结构化引用、填充和公式错误排查，制作税额与乘法表示例。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 入门、规范录入与练习数据","link":"/tools/office/excel/start"},"next":{"text":"Excel 条件判断、计数与汇总","link":"/tools/office/excel/aggregate"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 入门、规范录入与练习数据","link":"/tools/office/excel/start"},"next":{"text":"Excel 条件判断、计数与汇总","link":"/tools/office/excel/aggregate"}},"headers":[],"relativePath":"tools/office/excel/formulas.md","filePath":"tools/office/excel/formulas.md"}'),n={name:"tools/office/excel/formulas.md"},g=Object.assign(n,{setup(h){const a={path:"/tools/office/excel/formulas",app:"Excel",title:"向下填充时固定参数不跑偏",steps:[{tab:"开始",command:"数字格式",setting:"数量与单价为数值；参数 K1：0.9",anchor:"walkthrough-1"},{tab:"开始",command:"填充",setting:"区域：I2:I9；方向：向下",anchor:"walkthrough-2"},{tab:"公式",command:"计算选项",setting:"计算方式：自动；修改 K1：0.8",anchor:"walkthrough-3"}]};return(p,e)=>{const c=d("OfficeGuide");return r(),l("div",null,[e[0]||(e[0]=t("h1",{id:"excel-公式、相对引用与绝对引用",tabindex:"-1"},[o("Excel 公式、相对引用与绝对引用 "),t("a",{class:"header-anchor",href:"#excel-公式、相对引用与绝对引用","aria-label":'Permalink to "Excel 公式、相对引用与绝对引用"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("先完成"),t("a",{href:"/tools/office/excel/start#data"},"订单练习数据"),o("。公式以 "),t("code",null,"="),o(" 开始，保存的是计算规则。复制公式时引用是否移动，是初学 Excel 最需要理解的规则之一。")],-1)),i(c,{guide:a}),e[2]||(e[2]=s('<h2 id="syntax" tabindex="-1">运算与函数 <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;运算与函数 {#syntax}&quot;">​</a></h2><p><code>=2+3*4</code> 得到 14，<code>=(2+3)*4</code> 得到 20。乘除优先于加减，需要明确分组时加括号。文本放在英文双引号中，用 <code>&amp;</code> 连接，例如 <code>=&quot;订单：&quot;&amp;A2</code>。比较运算包括 <code>=</code>、<code>&lt;&gt;</code>、<code>&gt;</code>、<code>&lt;=</code> 等，结果是 TRUE 或 FALSE。</p><p>输入公式时使用半角符号。函数名称后紧跟括号，如 <code>=SUM(H2:H9)</code>；区域中间用冒号，多个参数用逗号或本机区域设置要求的分号。公式返回数字和返回文本是两回事，<code>=&quot;100&quot;</code> 不是普通数值 100。</p><h2 id="references" tabindex="-1">三种引用 <a class="header-anchor" href="#references" aria-label="Permalink to &quot;三种引用 {#references}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>向右复制一列</th><th>向下复制一行</th><th>用途</th></tr></thead><tbody><tr><td><code>A1</code></td><td><code>B1</code></td><td><code>A2</code></td><td>随位置变化的明细</td></tr><tr><td><code>$A$1</code></td><td><code>$A$1</code></td><td><code>$A$1</code></td><td>固定参数</td></tr><tr><td><code>$A1</code></td><td><code>$A1</code></td><td><code>$A2</code></td><td>固定列、行可变</td></tr><tr><td><code>A$1</code></td><td><code>B$1</code></td><td><code>A$1</code></td><td>固定行、列可变</td></tr></tbody></table><p>在编辑公式并选中引用时，Windows 桌面版通常可按 <code>F4</code> 循环切换引用形式；部分键盘需同时按 <code>Fn</code>。公式里的美元符号用于锁定位置，与货币格式无关。</p><h2 id="parameter" tabindex="-1">做一个含固定参数的计算 <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;做一个含固定参数的计算 {#parameter}&quot;">​</a></h2><p>在 <code>订单</code> 表 K1 输入“示例税率”，K2 输入 <code>6%</code>。这只是引用练习参数，不代表实际业务税率。I1 输入“示例税额”，I2 输入：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=ROUND(H2*$K$2,2)</span></span></code></pre></div><p>填充到 I9。第一行结果应为 14.40，最后一行是 54.00。若写成 <code>H2*K2</code>，向下填充会依次引用 K3、K4，导致结果错误。对金额进行四舍五入应按业务规则选择时点；“每行先舍入再合计”与“先合计再舍入”可能不同。</p><h2 id="tables" tabindex="-1">跨表与结构化引用 <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;跨表与结构化引用 {#tables}&quot;">​</a></h2><p>另一个工作表中可写 <code>=SUM(订单!H2:H9)</code>。工作表名含空格等字符时需加单引号，例如 <code>=&#39;月度 订单&#39;!H2</code>。引用其他工作簿会形成外部依赖，移动或改名可能造成链接问题。</p><p>对于命名为 <code>Sales</code> 的 Excel 表格，<code>=SUM(Sales[金额])</code> 会引用该表金额列的数据区域，表格正常扩展后引用也会扩展；<code>=[@数量]*[@单价]</code> 表示当前行数量乘单价。不要把结构化引用中的列标题改名与普通文本替换混为一谈。</p><h2 id="errors" tabindex="-1">公式为什么不更新 <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;公式为什么不更新 {#errors}&quot;">​</a></h2><p>先看单元格是否处于文本格式或公式前有单引号，再看是否启用了“显示公式”。公式值不刷新时检查“公式 → 计算选项”是否为自动；不要长期靠手动输入结果掩盖未更新。</p><p>常见错误包括除零 <code>#DIV/0!</code>、引用失效 <code>#REF!</code>、名称错误 <code>#NAME?</code>、查找不到 <code>#N/A</code>。使用“公式 → 追踪引用单元格”和“公式求值”定位输入。不要一开始就把所有公式包在 <code>IFERROR(...,0)</code> 中，否则真正的错误会变成看似合法的零。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>在新表 B1:D1 输入 1、2、3，A2:A4 输入 1、2、3，在 B2 输入 <code>=$A2*B$1</code>，向右向下填充。右下角 D4 应为 9，中间 C3 应为 4。解释为什么一个引用锁列、另一个锁行，再修改任一行列标题观察对应结果变化。</p><p>进阶计算继续阅读<a href="/tools/office/excel/aggregate">条件汇总</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：向下填充时固定参数不跑偏 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：向下填充时固定参数不跑偏 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：准备一列可验证的计算 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：准备一列可验证的计算 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 数字格式。</strong></p><p>在订单副本的 K1 输入 0.9，K2 写“折扣系数”作为说明；在 I1 输入折后金额。确认 K1 是数字而非文本，在 I2 输入 =E2<em>F2</em>$K$1。按回车后第一条结果应为 216，编辑栏中的两个美元符号锁定参数列和行。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：比较相对引用和绝对引用 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：比较相对引用和绝对引用 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 填充。</strong></p><p>选 I2:I9，使用“开始 → 填充 → 向下”或 Ctrl+D。点击 I3，公式中的 E2、F2 应变成 E3、F3，而 $K$1 不变。若使用表格计算列，也检查整列填充后的引用含义。不要靠逐行手改公式维持同一个参数。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用改参数检验公式依赖 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用改参数检验公式依赖 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：公式 → 计算选项。</strong></p><p>把 K1 改为 0.8，第一条折后金额应变为 192，其余订单同步变化。若没有更新，先检查公式计算选项是否为自动，再检查 I 列是否被粘贴成固定数值。恢复 0.9 后再保存，避免改变后续章节原金额 H 列的核对口径。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>原金额 H 列仍使用数量乘单价，折扣只在新增 I 列演示。不要把折扣覆盖进源单价，否则后面的 5120、4060、3160 将不再对应同一份练习数据。</p>',32))])}}});export{u as __pageData,g as default};
